import React from "react";
import AdoptionInfoHeader from "./components/AdoptionInfoHeader/AdoptionInfoHeader";
import FirstAdoptionInfoContainer from "./components/FirstAdoptionInfoContainer/FirstAdoptionInfoContainer";
import SecondAdoptionInfoContainer from "./components/SecondAdoptionInfoContainer/SecondAdoptionInfoContainer";
import ThirdAdoptionInfoContainer from "./components/ThirdAdoptionInfoContainer/ThirdAdoptionInfoContainer";
import AdoptionSearchBar from "./components/AdoptionSearchBar/AdoptionSearchBar";
import AdoptionCard from "./components/AdoptionCard/AdoptionCard";
import { useState } from "react";

const App = () => {
  const [searchTerm, setSearchTerm] = useState("");

  const animals = [
    {
      id: 1,
      image: "https://via.placeholder.com/250",
      name: "Bella",
      details: "Friendly and playful dog",
      place: "New York Shelter",
    },
    {
      id: 2,
      image: "https://via.placeholder.com/250",
      name: "Charlie",
      details: "Loves cuddles and walks",
      place: "California Shelter",
    },
    {
      id: 3,
      image: "https://via.placeholder.com/250",
      name: "Luna",
      details: "Calm and affectionate cat",
      place: "Florida Shelter",
    },
    {
      id: 4,
      image: "https://via.placeholder.com/250",
      name: "Max",
      details: "Energetic and loyal dog",
      place: "Texas Shelter",
    },
    {
      id: 5,
      image: "https://via.placeholder.com/250",
      name: "Daisy",
      details: "Sweet and gentle rabbit",
      place: "Nevada Shelter",
    },
  ];

  const filteredAnimals = animals.filter((animal) =>
    animal.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSearch = (event) => {
    setSearchTerm(event.target.value);
  };

  return (
    <div className="app">
      <h1>Animal Adoption</h1>
      <div className="search-bar">
        <AdoptionSearchBar />
        <input
          type="text"
          placeholder="Search for an animal..."
          value={searchTerm}
          onChange={handleSearch}
        />
      </div>
      <div className="row">
        {filteredAnimals.map((animal) => (
          <AdoptionCard
            key={animal.id}
            image={animal.image}
            name={animal.name}
            details={animal.details}
            place={animal.place}
          />
        ))}
      </div>
    </div>
  );
};

export default App;
